  "Per le condizioni giuridiche e commerciali complete consulta i documenti pubblicati nel footer. Per un problema relativo a uno specifico ordine, verifica prima le informazioni del Venditore e dell'ordine.": "Die vollständigen rechtlichen und kommerziellen Bedingungen finden Sie in den in der Fußzeile veröffentlichten Dokumenten. Bei einem Problem im Zusammenhang mit einer bestimmten Bestellung überprüfen Sie zunächst die Verkäufer- und Bestellinformationen.",
