  "Castrovillari vive tutto l'anno attraverso teatro, musica, folklore, libri, arte e iniziative di comunità. Il calendario cambia di anno in anno: per date confermate e programmi completi fai riferimento agli organizzatori.": "Castrovillari lebt das ganze Jahr über durch Theater, Musik, Folklore, Bücher, Kunst und Gemeinschaftsinitiativen. Der Kalender ändert sich von Jahr zu Jahr: Für bestätigte Termine und vollständige Programme wenden Sie sich bitte an die Organisatoren.",
  "Da non perdere": "Nicht verpassen",
  "Gusto e territorio": "Geschmack und Territorium",
  "Scopri le tradizioni gastronomiche di Castrovillari e del Pollino, compresa la Cipolla Bianca di Castrovillari, riconosciuta De.Co. Per produttori, stagionalità e iniziative enogastronomiche consulta le fonti locali e gli eventi in programma.": "Entdecken Sie die gastronomischen Traditionen von Castrovillari und Pollino, einschließlich der weißen Zwiebel von Castrovillari, anerkannt von De.Co. Informationen zu Produzenten, Saisonalität sowie Lebensmittel- und Weininitiativen finden Sie in lokalen Quellen und geplanten Veranstaltungen.",
