  "Il tuo riepilogo personale: ordini, preferiti, offerte ed eventi.": "Ihre persönliche Zusammenfassung: Bestellungen, Favoriten, Angebote und Veranstaltungen.",
  "Il riepilogo della tua attività su Radici Calabria: ordini, preferiti e ultimi acquisti, sempre a portata di mano.": "Die Zusammenfassung Ihrer Aktivitäten auf Radici Calabria: Bestellungen, Favoriten und letzte Einkäufe immer zur Hand.",
  "Storico dei tuoi ordini con lo stato di spedizione e consegna.": "Verlauf Ihrer Bestellungen mit Versand- und Lieferstatus.",
  "Lo storico completo dei tuoi acquisti, salvato sul tuo account: ritorna quando vuoi e ritrova ogni ordine con il suo stato.": "Der vollständige Verlauf Ihrer Einkäufe wird in Ihrem Konto gespeichert: Kommen Sie jederzeit zurück und finden Sie jede Bestellung mit ihrem Status.",
  "Negozi e prodotti salvati per non perderli di vista.": "Stores und Produkte werden gespeichert, damit Sie sie nicht aus den Augen verlieren.",
  "I negozi e i prodotti che hai salvato per non perderli di vista.": "Die Shops und Produkte, die Sie gespeichert haben, damit Sie sie nicht aus den Augen verlieren.",
  "Hai un account? I tuoi ordini restano qui per sempre.": "Haben Sie ein Konto? Ihre Bestellungen bleiben für immer hier.",
  "I tuoi ordini restano al sicuro: servono entrambi i dati per trovarli": "Ihre Bestellungen bleiben sicher: Sie benötigen beide Daten, um sie zu finden",
  "Puoi recuperare i tuoi ordini in qualsiasi momento inserendo email e telefono usati al checkout.": "Sie können Ihre Bestellungen jederzeit abrufen, indem Sie die beim Bezahlvorgang verwendete E-Mail-Adresse und Telefonnummer eingeben.",
  "Hai acquistato senza account? Inserisci l'email e il telefono usati al momento dell'ordine.": "Haben Sie ohne Konto gekauft? Geben Sie die E-Mail-Adresse und Telefonnummer ein, die Sie bei der Bestellung verwendet haben.",
  "Inserisci sia l'email sia il telefono usati per l'ordine.": "Geben Sie sowohl die E-Mail-Adresse als auch die Telefonnummer ein, die Sie für die Bestellung verwendet haben.",
  "Verifica che email e telefono coincidano con quelli usati al checkout.": "Überprüfen Sie, ob Ihre E-Mail-Adresse und Telefonnummer mit denen beim Bezahlen übereinstimmen.",
  "Puoi ritrovare questo ordine in qualsiasi momento dalla tua area personale, anche dopo aver chiuso il browser.": "Diese Bestellung können Sie jederzeit in Ihrem persönlichen Bereich einsehen, auch nach Schließen des Browsers.",
  "Se ti registri e accedi come cliente, i tuoi prossimi acquisti compariranno automaticamente nella tua area personale.": "Wenn Sie sich als Kunde registrieren und anmelden, erscheinen Ihre nächsten Einkäufe automatisch in Ihrem persönlichen Bereich.",
