  "Tariffa di spedizione calcolata automaticamente da Radici Calabria in base al corriere e alle caratteristiche della spedizione.": "Der Versandtarif wird von Radici Calabria automatisch basierend auf dem Kurier und den Merkmalen der Sendung berechnet.",
  "Il checkout non ha prodotti: impossibile avviare il pagamento.": "An der Kasse sind keine Produkte vorhanden: Die Zahlung konnte nicht eingeleitet werden.",
  "L'ordine non ha prodotti: impossibile avviare il pagamento.": "Die Bestellung enthält keine Produkte: Die Zahlung konnte nicht eingeleitet werden.",
  "Il carrello deve contenere da 1 a 50 prodotti.": "Der Warenkorb muss 1 bis 50 Produkte enthalten.",
  "Un prodotto del carrello non è più disponibile.": "Ein Produkt in Ihrem Warenkorb ist nicht mehr verfügbar.",
  "Impossibile avviare il pagamento: totale dell'ordine non coerente.": "Zahlung konnte nicht eingeleitet werden: Bestellsumme inkonsistent.",
  "Il metodo di pagamento di questo checkout non è disponibile.": "Die Zahlungsmethode dieser Kasse ist nicht verfügbar.",
  "Il metodo di pagamento non è più configurato per il negozio.": "Die Zahlungsart ist für den Shop nicht mehr konfiguriert.",
  "Nessun pagamento gateway rimborsabile su questo ordine.": "Für diese Bestellung ist keine erstattungsfähige Gateway-Zahlung möglich.",
  "Il pagamento di questo ordine è stato ricevuto": "Die Zahlung für diese Bestellung ist eingegangen",
  "Alcuni negozi non hanno completato l'ordine: le relative righe sono ancora nel carrello per essere corrette.": "Einige Geschäfte haben die Bestellung noch nicht abgeschlossen: Die entsprechenden Zeilen befinden sich noch im Warenkorb und müssen korrigiert werden.",
  "Con più negozi ogni ordine ha la propria sessione di pagamento: ti mostreremo un pulsante per negozio.": "Bei mehreren Filialen hat jede Bestellung ihre eigene Checkout-Sitzung – wir zeigen Ihnen eine Schaltfläche pro Filiale.",
  "Correggi e riprova i negozi mancanti": "Bitte beheben Sie die fehlenden Geschäfte und versuchen Sie es erneut",
  "Nessun importo è stato addebitato e nessun ordine è stato creato.": "Es wurde kein Betrag abgebucht und keine Bestellung erstellt.",
  "Nessun importo è stato addebitato finché il pagamento non è confermato.": "Bis zur Bestätigung der Zahlung wurde kein Betrag abgebucht.",
  "Il pagamento è stato rimborsato: nessun nuovo ordine verrà creato.": "Die Zahlung wurde zurückerstattet – es werden keine neuen Bestellungen erstellt.",
  "Il tempo per completare il pagamento è terminato: nessun ordine è stato creato e le scorte sono state liberate. Puoi effettuare un nuovo acquisto.": "Die Zeit zum Abschluss der Zahlung ist abgelaufen: Es wurden keine Bestellungen erstellt und Lagerbestände wurden freigegeben. Sie können einen Neukauf tätigen.",
  "Il rimborso è in riconciliazione. La pratica resta nello stato attuale.": "Die Rückerstattung erfolgt im Ausgleich. Die Praxis bleibt in ihrem aktuellen Zustand.",
  "Rimborso in riconciliazione. Non ripetere l'operazione con una nuova chiave.": "Rückerstattung bei Versöhnung. Wiederholen Sie den Vorgang nicht mit einem neuen Schlüssel.",
  "Serve al corriere locale per raggiungere esattamente il punto indicato. Consenti la posizione quando richiesto dal browser.": "Es wird vom örtlichen Kurier verwendet, um den angegebenen Punkt genau zu erreichen. Erlauben Sie den Standort, wenn Sie vom Browser dazu aufgefordert werden.",
