  "Attrazioni ed eventi a Castrovillari": "Attraktionen und Veranstaltungen in Castrovillari",
  "Il titolo è obbligatorio.": "Der Titel ist obligatorisch.",
  "Il titolo dell'offerta è obbligatorio.": "Der Titel des Angebots ist zwingend erforderlich.",
  "Il titolo non può superare 150 caratteri.": "Der Titel darf 150 Zeichen nicht überschreiten.",
