  "La descrizione deve essere testo.": "Die Beschreibung muss aus Text bestehen.",
  "Il luogo deve essere testo.": "Der Ort muss Text sein.",
  "immagine_url deve essere testo.": "url_image muss Text sein.",
  "Offerta creata ma non leggibile dal pannello.": "Angebot erstellt, aber für das Panel nicht lesbar.",
  "Articoli e contenuti editoriali della città: storie, approfondimenti e notizie dal territorio.": "Artikel und redaktionelle Inhalte aus der Stadt: Geschichten, Einblicke und Neuigkeiten aus der Region.",
  "Non ci sono ancora notizie disponibili.": "Es liegen noch keine Neuigkeiten vor.",
  "L'aggregatore raccoglie le notizie di Castrovillari periodicamente. Torna presto a trovarci.": "Der Aggregator sammelt regelmäßig Castrovillari-Nachrichten. Kommen Sie bald wieder vorbei und besuchen Sie uns.",
  "Le notizie di Castrovillari raccolte automaticamente da fonti istituzionali e pubbliche: Comune, Provincia, Regione, Parco del Pollino e Protezione Civile.": "Castrovillari-Nachrichten werden automatisch aus institutionellen und öffentlichen Quellen gesammelt: Gemeinde, Provinz, Region, Pollino-Park und Katastrophenschutz.",
  "Google News · Castrovillari": "Google News · Castrovillari",
  "Google News · Castrovillari Comune": "Google News · Gemeinde Castrovillari",
  "Radici Calabria collega produttori, trasformatori, distributori e consumatori: le filiere dei territori arrivano in città.": "Radici Calabria verbindet Produzenten, Verarbeiter, Händler und Verbraucher: Die lokalen Lieferketten kommen in der Stadt an.",
  "Una piattaforma che valorizza le produzioni, le imprese e le identità territoriali, collegando produttori, trasformatori, distributori e consumatori.": "Eine Plattform, die Produktionen, Unternehmen und territoriale Identitäten stärkt und Produzenten, Verarbeiter, Händler und Verbraucher miteinander verbindet.",
  "Le offerte e le promozioni dei produttori e dei negozi del territorio: prodotti in sconto selezionati tra le filiere locali.": "Angebote und Aktionen von lokalen Produzenten und Geschäften: rabattierte Produkte, ausgewählt aus lokalen Lieferketten.",
  "Le migliori offerte dei negozi di Castrovillari": "Die besten Angebote der Geschäfte in Castrovillari",
  "Le eccellenze di Castrovillari e del Pollino: cipolle bianche, mieli e prodotti tipici selezionati dalle filiere del territorio.": "Die Exzellenz von Castrovillari und Pollino: weiße Zwiebeln, Honig und typische Produkte aus lokalen Lieferketten.",
  "Scopri monumenti, musei, cultura, eventi, sapori e borghi nei dintorni di Castrovillari e del Parco Nazionale del Pollino.": "Entdecken Sie Denkmäler, Museen, Kultur, Veranstaltungen, Aromen und Dörfer in der Umgebung von Castrovillari und im Nationalpark Pollino.",
  "Non ci sono ancora prodotti in promozione. Esplora i negozi e le produzioni del territorio.": "Es sind noch keine Produkte im Angebot. Entdecken Sie die örtlichen Geschäfte und Produkte.",
  "Non ci sono ancora prodotti nella vetrina territoriale. Esplora i negozi e le produzioni del territorio.": "Es sind noch keine Produkte in der lokalen Vitrine vorhanden. Entdecken Sie die örtlichen Geschäfte und Produkte.",
  "Presto potrai trovare promozioni esclusive dai negozi della tua città.": "Bald finden Sie exklusive Sonderangebote von Geschäften in Ihrer Stadt.",
  "I prodotti dei negozi locali saranno visibili qui appena disponibili.": "Produkte aus lokalen Geschäften werden hier angezeigt, sobald sie verfügbar sind.",
  "Aggiungi prodotti dalle filiere del territorio prima di procedere al checkout.": "Fügen Sie Produkte aus lokalen Lieferketten hinzu, bevor Sie zur Kasse gehen.",
  "Completa il tuo ordine su Radici Calabria: ritiro o spedizione dai produttori e dai negozi del territorio.": "Schließen Sie Ihre Bestellung bei Radici Calabria ab: Abholung oder Versand bei lokalen Herstellern und Geschäften.",
  "Acquista senza account oppure accedi per usare i dati del tuo profilo.": "Kaufen Sie ohne Konto oder melden Sie sich an, um Ihre Profildaten zu verwenden.",
  "Stai acquistando come ospite: non è richiesta la registrazione, compila i tuoi dati per l'ordine.": "Sie kaufen als Gast ein: Eine Registrierung ist nicht erforderlich, geben Sie Ihre Bestelldaten ein.",
  "Stai acquistando come ospite: non è richiesta la registrazione, indica solo chi ritira.": "Sie kaufen als Gast ein: Eine Anmeldung ist nicht erforderlich, geben Sie einfach an, wer abholt.",
  "Stai acquistando come ospite: compila i tuoi dati qui sotto. Non è richiesta la registrazione.": "Sie kaufen als Gast: Geben Sie unten Ihre Daten ein. Eine Anmeldung ist nicht erforderlich.",
  "Usiamo l'indirizzo del tuo profilo. Puoi cambiarlo solo per questo ordine senza modificare il profilo.": "Wir verwenden Ihre Profiladresse. Sie können es nur für diese Bestellung ändern, ohne das Profil zu ändern.",
  "Puoi cambiarlo solo per questo ordine senza modificare il profilo.": "Sie können es nur für diese Bestellung ändern, ohne das Profil zu ändern.",
  "Account Google autenticato. Completa solo i dati dell'attività per concludere la registrazione.": "Authentifiziertes Google-Konto. Geben Sie nur die Geschäftsdaten ein, um die Registrierung abzuschließen.",
  "Registrazione completata e accesso effettuato. Il tuo account è ora in attesa dell'approvazione dell'amministratore prima di poter utilizzare le aree personali della piattaforma.": "Registrierung abgeschlossen und angemeldet. Ihr Konto wartet nun auf die Genehmigung durch den Administrator, bevor Sie die persönlichen Bereiche der Plattform nutzen können.",
  "Ti abbiamo inviato una email di conferma della registrazione. Non devi fare altro: riceverai una nuova comunicazione quando l'amministratore avrà deciso.": "Wir haben Ihnen eine E-Mail zur Bestätigung Ihrer Registrierung gesendet. Sie müssen nichts weiter tun: Sie erhalten eine neue Mitteilung, sobald der Administrator entschieden hat.",
  "Ti abbiamo inviato un'email per confermare la registrazione. Clicca sul link contenuto nel messaggio per attivare il tuo account.": "Wir haben Ihnen eine E-Mail zur Bestätigung Ihrer Registrierung gesendet. Klicken Sie auf den Link in der Nachricht, um Ihr Konto zu aktivieren.",
  "Controlla la posta in arrivo e la cartella spam.": "Überprüfen Sie Ihren Posteingang und Spam-Ordner.",
  "Non hai ricevuto il messaggio? Controlla la cartella spam o riprova tra qualche minuto.": "Haben Sie die Nachricht nicht erhalten? Bitte überprüfen Sie Ihren Spam-Ordner oder versuchen Sie es in ein paar Minuten erneut.",
  "Se l'account esiste e non è ancora confermato, ti abbiamo reinviato l'email di conferma. Controlla la posta in arrivo e la cartella spam.": "Wenn das Konto existiert und noch nicht bestätigt ist, haben wir Ihnen die Bestätigungs-E-Mail erneut gesendet. Überprüfen Sie Ihren Posteingang und Spam-Ordner.",
  "Link di recupero inviato. Apri il messaggio e segui le istruzioni.": "Wiederherstellungslink gesendet. Öffnen Sie die Nachricht und folgen Sie den Anweisungen.",
  "Non hai ricevuto l'email di conferma?": "Sie haben die Bestätigungs-E-Mail nicht erhalten?",
