  "Cerca farmacie aperte, di turno o tutte.": "Suchen Sie nach Apotheken, die geöffnet, im Dienst oder alle geöffnet sind.",
  "Ciao! Sono l'Assistente di LocalHub": "HALLO! Ich bin der LocalHub-Assistent",
  "Cerca offerte, promozioni e sconti attivi.": "Suchen Sie nach aktiven Angeboten, Aktionen und Rabatten.",
  "Cerca eventi, manifestazioni e appuntamenti.": "Suchen Sie nach Veranstaltungen, Vorführungen und Terminen.",
