  "Restituisce il meteo aggiornato di Castrovillari.": "Gibt das aktualisierte Wetter von Castrovillari zurück.",
  "Cerca negozi, attività, professionisti e servizi locali.": "Suchen Sie nach lokalen Geschäften, Unternehmen, Fachleuten und Dienstleistungen.",
