  "© 2026 Radici Calabria · Castrovillari · Privacy · Termini e condizioni": "© 2026 Radici Kalabrien · Castrovillari · Datenschutz · Allgemeine Geschäftsbedingungen",
  "Accesso negato. La verifica ha rilevato un'età inferiore ai 18 anni. Potrai riprovare dopo il periodo di blocco.": "Zugriff verweigert. Die Überprüfung ergab, dass er unter 18 Jahre alt war. Nach Ablauf der Sperrfrist können Sie es erneut versuchen.",
