  "Torrone di Bagnara IGP": "Bagnara IGP-Nougat",
  "Pesca costiera tra Tirreno e Ionio, acquacoltura e tradizioni marinare: dalle marinerie di Scilla e Bagnara ai porti del Crotonese.": "Küstenfischerei zwischen Tyrrhenischem und Ionischem Meer, Aquakultur und maritime Traditionen: von den Yachthäfen von Scilla und Bagnara bis zu den Häfen von Crotone.",
  "Le marinerie dello Stretto lavorano pesce azzurro, alici e pesce spada con tecniche tramandate di padre in figlio; lungo lo Ionio l'acquacoltura alleva orate e branzini in mare aperto, in gabbie ancorate al largo.": "In den Jachthäfen der Meerenge werden Blaufisch, Sardellen und Schwertfisch mit Techniken verarbeitet, die vom Vater an den Sohn weitergegeben wurden. Entlang des Ionischen Meeres werden in der Aquakultur Seebrasse und Wolfsbarsch im offenen Meer in vor der Küste verankerten Käfigen gezüchtet.",
  "La filiera corta dei porti rifornisce pescherie e ristoranti con il pescato del giorno. Alici e sardine si conservano sott'olio o sotto sale, mentre il pesce spada si lavora a trancio già sulla banchina, tra ghiaccio e casse.": "Die kurze Lieferkette in den Häfen versorgt Fischhändler und Restaurants mit dem Fang des Tages. Sardellen und Sardinen werden in Öl oder Salz eingelegt, während Schwertfisch direkt am Dock zwischen Eis und Kisten geschnitten wird.",
  "Pesca costiera notturna o all'alba, con reti e palangari": "Küstenangeln bei Nacht oder im Morgengrauen mit Netzen und Langleinen",
  "Selezione e ghiaccio a bordo, poi asta del pesce al porto": "Auswahl und Eis an Bord, anschließend Fischauktion im Hafen",
  "Conservazione sott'olio, sotto sale o abbattimento per il fresco": "Konservierung in Öl, Salz oder Schockkühlung zur Frischlagerung",
  "Pesce azzurro soprattutto in primavera ed estate; pesce spada da maggio a settembre.": "Blauer Fisch, besonders im Frühling und Sommer; Schwertfisch von Mai bis September.",
