  "Per informazioni sui negozi, sui prodotti o sul funzionamento della piattaforma scrivici: ti rispondiamo il prima possibile.": "Für Informationen zu den Shops, Produkten oder zur Funktionsweise der Plattform schreiben Sie uns: Wir werden so schnell wie möglich antworten.",
  "Per un problema relativo a un ordine specifico, contatta prima il Venditore attraverso i recapiti indicati nella scheda del negozio o dell'ordine. Per il supporto tecnico sulla piattaforma puoi scriverci": "Bei einem Problem im Zusammenhang mit einer bestimmten Bestellung wenden Sie sich zunächst über die im Shop oder auf der Bestellkarte angegebenen Kontaktdaten an den Verkäufer. Für technischen Support auf der Plattform können Sie uns schreiben",
