  "TerraQ è il servizio di Radici Calabria per riconoscere e verificare i prodotti. Questa pagina è pronta per ospitarlo.": "TerraQ ist der Dienst von Radici Calabria zur Erkennung und Prüfung von Produkten. Diese Seite ist bereit, ihn aufzunehmen.",
  "Servizio in arrivo": "Dienst in Kürze verfügbar",
  "Nel frattempo il catalogo dei prodotti resta disponibile nella sezione Filiere, con categorie, schede prodotto, prezzi, disponibilità e acquisto.": "In der Zwischenzeit bleibt der Produktkatalog im Bereich Lieferketten verfügbar, mit Kategorien, Produktseiten, Preisen, Verfügbarkeit und Kauf.",
  "La rinascita verde della Calabria": "Die grüne Wiedergeburt Kalabriens",
  "Quattro anni di crescita record, innovazione e conquista dei mercati globali.": "Vier Jahre Rekordwachstum, Innovation und Eroberung globaler Märkte.",
  "C’è una Calabria che non si limita a custodire le proprie tradizioni millenarie, ma le trasforma in un motore economico moderno, competitivo e riconosciuto in tutto il mondo. Negli ultimi quattro anni, tra il 2022 e il 2026, il comparto agroalimentare calabrese è stato protagonista di una vera e propria svolta strutturale: un percorso fatto di numeri da primato, investimenti mirati e una visione istituzionale condivisa che ha saputo fare squadra con gli agricoltori, portando le eccellenze della regione sulle tavole internazionali.": "Es gibt ein Kalabrien, das sich nicht darauf beschränkt, seine tausendjährigen Traditionen zu bewahren, sondern sie in einen modernen, wettbewerbsfähigen und weltweit anerkannten Wirtschaftsmotor umzuwandeln. In den letzten vier Jahren, zwischen 2022 und 2026, war der kalabrische Agrar- und Ernährungssektor der Protagonist eines echten strukturellen Wendepunkts: ein Weg, der aus Rekordzahlen, gezielten Investitionen und einer gemeinsamen institutionellen Vision bestand, der es gelang, mit den Landwirten zusammenzuarbeiten und die Exzellenz der Region auf internationale Tische zu bringen.",
  "incidenza agricoltura sul PIL regionale": "Auswirkungen der Landwirtschaft auf das regionale BIP",
