  "La società [Inserisci Nome Azienda/Ditta] (di seguito, il “Gestore”) mette a disposizione degli utenti una piattaforma tecnologica web e i relativi servizi digitali e di comunicazione (di seguito, il “Sito” o la “Piattaforma”), finalizzati a consentire l'incontro, l'interazione e la conclusione di rapporti commerciali tra venditori indipendenti (di seguito, i “Venditori”) e potenziali acquirenti (di seguito, gli “Acquirenti”).": "Das Unternehmen [Unternehmen/Firmennamen einfügen] (im Folgenden „Verwalter“) stellt den Nutzern eine Web-Technologieplattform und die damit verbundenen digitalen und Kommunikationsdienste (im Folgenden „Website“ oder „Plattform“) zur Verfügung, die darauf abzielt, die Begegnung, Interaktion und den Abschluss von Geschäftsbeziehungen zwischen unabhängigen Verkäufern (im Folgenden „Verkäufer“) und potenziellen Käufern (im Folgenden „Käufer“) zu ermöglichen.",
