  ": il soggetto che consulta un'offerta o acquista dal Venditore.": ": die Person, die ein Angebot einsieht oder beim Verkäufer kauft.",
  ": il soggetto che pubblica un'offerta e propone al cliente un prodotto, un servizio o altra prestazione.": ": die Person, die ein Angebot veröffentlicht und dem Kunden ein Produkt, eine Dienstleistung oder eine andere Bereitstellung vorschlägt.",
  ": il soggetto che utilizza Radici Calabria per pubblicare e offrire prodotti, servizi o altre prestazioni.": ": die Person, die Radici Calabria nutzt, um Produkte, Dienstleistungen oder andere Dienstleistungen zu veröffentlichen und anzubieten.",
  ": il soggetto terzo che fornisce l'infrastruttura tecnica per il metodo di pagamento selezionato.": ": der Dritte, der die technische Infrastruktur für die ausgewählte Zahlungsmethode bereitstellt.",
