  ": la piattaforma e l'infrastruttura tecnologica gestita da [Inserisci Nome Azienda/Ditta].": ": die von [Firmennamen einfügen] verwaltete Plattform und technologische Infrastruktur.",
  ": la proposta relativa a un prodotto, servizio o prestazione pubblicata dal Venditore.": ": das vom Verkäufer veröffentlichte Angebot für ein Produkt, eine Dienstleistung oder eine Bereitstellung.",
  ": la richiesta del Cliente relativa a un'offerta, secondo il flusso applicabile.": ": die Anfrage des Kunden nach einem Angebot gemäß dem geltenden Ablauf.",
  ": la richiesta di acquisto o prenotazione riferita a un'offerta del venditore, secondo il flusso applicabile.": ": die Kauf- oder Reservierungsanfrage, die sich auf ein Angebot des Verkäufers bezieht, je nach anwendbarem Ablauf.",
  ": lo spazio o profilo del Venditore pubblicato sulla piattaforma.": ": der auf der Plattform veröffentlichte Bereich oder das Profil des Verkäufers.",
  "Il Gestore non acquista, non rivende e non commercializza in proprio i prodotti o i servizi offerti dai Venditori.": "Der Manager kauft, verkauft oder vermarktet die von den Verkäufern angebotenen Produkte oder Dienstleistungen nicht selbst.",
  "Il trattamento dei dati personali avviene secondo l'Informativa Privacy di Radici Calabria e la normativa applicabile, incluso il Regolamento (UE) 2016/679 (GDPR). Ciascun utente professionale opera quale autonomo titolare del trattamento per i dati trattati nell'ambito delle proprie attività, nei limiti e secondo le rispettive responsabilità previste dalla normativa applicabile.": "Die Verarbeitung personenbezogener Daten erfolgt gemäß der Datenschutzrichtlinie von Radici Calabria und den geltenden Gesetzen, einschließlich der Verordnung (EU) 2016/679 (DSGVO). Jeder professionelle Nutzer agiert als unabhängiger Datenverantwortlicher für die im Rahmen seiner Tätigkeit verarbeiteten Daten im Rahmen und gemäß den jeweiligen Verantwortlichkeiten, die durch die geltenden Rechtsvorschriften festgelegt sind.",
  "La Piattaforma integra e utilizza servizi, contenuti e strumenti informativi forniti da soggetti terzi, inclusi i componenti e i widget informativi resi disponibili all'interno della Piattaforma. I dati, le informazioni, gli aggiornamenti e i risultati visualizzati attraverso tali componenti sono forniti e gestiti dai rispettivi soggetti o servizi di origine. La responsabilità dell'esattezza, completezza, aggiornamento, disponibilità e continuità di tali dati e informazioni è a carico del relativo soggetto o servizio di origine, secondo le proprie condizioni e responsabilità. Radici Calabria non modifica né garantisce autonomamente tali dati e non assume responsabilità per eventuali inesattezze, ritardi, omissioni, indisponibilità o interruzioni imputabili al servizio o al soggetto che li fornisce, fatti salvi gli obblighi inderogabili previsti dalla legge.": "Die Plattform integriert und nutzt von Dritten bereitgestellte Dienste, Inhalte und Informationstools, einschließlich der auf der Plattform zur Verfügung gestellten Komponenten und Informations-Widgets. Die über solche Komponenten angezeigten Daten, Informationen, Aktualisierungen und Ergebnisse werden von den jeweiligen Ursprungseinheiten oder Diensten bereitgestellt und verwaltet. Die Verantwortung für die Richtigkeit, Vollständigkeit, Aktualisierung, Verfügbarkeit und Kontinuität dieser Daten und Informationen liegt bei der jeweiligen Urheberstelle oder dem betreffenden Dienst gemäß seinen eigenen Bedingungen und Verantwortlichkeiten. Radici Calabria übernimmt keine eigenständige Änderung oder Gewährleistung dieser Daten und übernimmt keine Verantwortung für etwaige Ungenauigkeiten, Verzögerungen, Auslassungen, Nichtverfügbarkeit oder Unterbrechungen, die auf den Dienst oder die Person, die ihn bereitstellt, zurückzuführen sind, unbeschadet der gesetzlich vorgeschriebenen zwingenden Verpflichtungen.",
  "aggiornare offerte, prezzi e disponibilità;": "Angebote, Preise und Verfügbarkeit aktualisieren;",
