  "potatura, fioritura, invaiatura, vendemmia e vinificazione": "Beschneiden, Blühen, Veraison, Ernte und Weinbereitung",
  "Fioriture, raccolta del miele e produzioni tradizionali.": "Blüte, Honigernte und traditionelle Produktionen.",
  "Calendario di raccolta per ecotipo e zona di produzione.": "Erntekalender nach Ökotyp und Produktionsgebiet.",
  "52 comuni tra le province di Crotone, Catanzaro e Cosenza": "52 Gemeinden zwischen den Provinzen Crotone, Catanzaro und Cosenza",
  "agrumeti della piana, castagneti di Sila e Aspromonte": "Zitrushaine der Ebene, Kastanienhaine von Sila und Aspromonte",
  "Novembre – Dicembre — Novembre": "November – Dezember – November",
