  "Bottega DEMO che raccoglie le Eccellenze del territorio di Castrovillari e del Pollino. Ambiente dimostrativo, non un'attività reale aderente a LocalHub.": "DEMO-Shop, der die Exzellenz der Gebiete Castrovillari und Pollino vereint. Demo-Umgebung, kein echtes LocalHub-Geschäft.",
  "Negozio DEMO dedicato ai dolci e ai sapori tradizionali di Castrovillari. Ambiente dimostrativo, non un'attività reale aderente a LocalHub.": "DEMO-Shop, der den traditionellen Desserts und Aromen von Castrovillari gewidmet ist. Demo-Umgebung, kein echtes LocalHub-Geschäft.",
  "Vetrina DEMO dei sapori del Parco Nazionale del Pollino: miele, olio e vino del territorio. Ambiente dimostrativo, non un'attività reale aderente a LocalHub.": "DEMO-Schaufenster der Aromen des Pollino-Nationalparks: lokaler Honig, Öl und Wein. Demo-Umgebung, kein echtes LocalHub-Geschäft.",
  "Enoteca DEMO dedicata ai vini dell'area del Pollino: le sottozone di Terre di Cosenza e il Moscato al governo di Saracena. Ambiente dimostrativo, non un'attività reale aderente a LocalHub.": "DEMO-Weinladen, der sich den Weinen des Pollino-Gebietes widmet: den Untergebieten Terre di Cosenza und Moscato unter der Regierung von Saracena. Demo-Umgebung, kein echtes LocalHub-Geschäft.",
